public @interface NotNull { String message() default "값이 필요합니다"; }

@Retention(RUNTIME) @Target(FIELD)
public @interface Size { int min() default 0; int max() default Integer.MAX_VALUE;
                         String message() default "길이가 맞지 않습니다"; }

@Retention(RUNTIME) @Target(FIELD)
public @interface Min { long value(); String message() default "너무 작습니다"; }

