    if (nn != null && v == null) { errors.add(f.getName() + ": " + nn.message()); continue; }

    Size sz = f.getAnnotation(Size.class);
    if (sz != null && v instanceof String s
        && (s.length() < sz.min() || s.length() > sz.max()))
        errors.add(f.getName() + ": " + sz.message() + " (...)");

    Min mn = f.getAnnotation(Min.class);
    if (mn != null && v instanceof Number n && n.longValue() < mn.value())
        errors.add(f.getName() + ": " + mn.message() + " (...)");
}

